template<class T,
         template<class> class Ownership = RefCounted,
         template<class> class Checking  = AssertCheck>
class SmartPtr : public Ownership<T>, public Checking<T> {
    T* p_;
public:
    explicit SmartPtr(T* p) : p_(p) { Checking<T>::check(p_); }
    ~SmartPtr() { Ownership<T>::release(p_); }
};
using WidgetPtr = SmartPtr<Widget, RefCounted, RejectNull>;

template<class T, class Ownership = RefCounted<T>, class Threading = SingleThreaded>
class SmartPtr : private Ownership, private Threading {
    T* p_;
public:
    explicit SmartPtr(T* p) : p_(p) {}
    ~SmartPtr() { Ownership::release(p_); }
    T* get() const { return p_; }
};
using WidgetPtr = SmartPtr<Widget, NoCopy<Widget>, MultiThreaded>;

